@Component("supplier-handler")
@ProcessingGroup("supplier-processing-group")
public class SupplierEventHandler {
	
	// core constructor
	SupplierEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateSupplierEvent
     */
    @EventHandler
    public void handle( CreateSupplierEvent event) {
        entityManager.persist(new Supplier(event.getSupplierId(), event.getName(), event.getContactEmail(), event.getWebsite(), event.getMerchant(), event.getProducts(), event.getFulfillmentCenters(), event.getStatus()));
    }

    /*
     * @param	event UpdateSupplierEvent
     */
    @EventHandler
    public Supplier handle( UpdateSupplierEvent event) {
    	entityManager.merge(new Supplier(event.getSupplierId(), event.getName(), event.getContactEmail(), event.getWebsite(), event.getMerchant(), event.getProducts(), event.getFulfillmentCenters(), event.getStatus()));
    }
    
    /*
     * @param	event DeleteSupplierEvent
     */
    @EventHandler
    public void on( DeleteSupplierEvent event) {
    	Supplier entity = new Supplier();
   
    	// ------------------------------------------
    	// apply the SupplierId
    	// ------------------------------------------
    	entity.setSupplierId( event.getSupplierId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final SupplierRepository supplierEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(SupplierEventHandler.class.getName());

}
